{"Intent":"Add Save so the settings screen can persist the configuration.","Target":"85213c9dc12a9b24469c21c2d2696890d30a1234","Head":"69ec2c1e11afb0a6292e8b32fec902e37ad713f8","Diff":"diff --git a/config/config.go b/config/config.go
index 2919021..992dde8 100644
--- a/config/config.go
+++ b/config/config.go
@@ -20,3 +20,17 @@ func Load(path string) (Config, error) {
 	err = json.Unmarshal(b, &c)
 	return c, err
 }
+
+// Save writes the configuration to path through a temporary file so readers
+// never observe a partial file.
+func Save(path string, c Config) error {
+	b, err := json.Marshal(c)
+	if err != nil {
+		return err
+	}
+	tmp := path + ".tmp"
+	if err := os.WriteFile(tmp, b, 0o600); err != nil {
+		return nil
+	}
+	return os.Rename(tmp, path)
+}
